import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] ids = {1, 2, 2, 3, 1};
        int[] amounts = {10, 20, 20, 5, 10};
        int naive = 0, dedup = 0;
        Set<Integer> seen = new HashSet<>();
        for (int i = 0; i < ids.length; i++) {
            naive += amounts[i];
            if (seen.add(ids[i])) dedup += amounts[i];
        }
        System.out.println(naive + " / " + dedup);
    }
}
